// Block (composition) — a self-contained account menu opened from an avatar trigger.
// Contract: docs/rules/block-contract.md. Arranges only (Stack for trigger layout);
// composes Avatar/Button/Menu and delegates item actions to the consumer. Mints no tokens.
import { Avatar } from "../components/Avatar";
import { Text } from "react-aria-components";
import { Button } from "../components/Button";
import { Menu, MenuItem } from "../components/Menu";
import "./UserMenu.css";

export interface UserMenuProps {
  /** User name shown beside the avatar and used for accessible image text. */
  name?: string;
  /** Avatar image source. */
  avatarSrc?: string;
  /** Account menu choices. */
  items: { id: string; label: string }[];
  /** Called with the selected item id. */
  onAction?: (id: string) => void;
  className?: string;
}

const initials = (name?: string) =>
  name
    ?.split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("") || "U";

export function UserMenu({ name, avatarSrc, items, onAction, className }: UserMenuProps) {
  const label = name ? `Open account menu for ${name}` : "Open account menu";

  return (
    <Menu
      aria-label="Account menu"
      onAction={(key) => onAction?.(String(key))}
      trigger={
        /* usage: chrome — a trigger meant for a bar or rail footer slot */
        <Button
          variant="secondary"
          size="small"
          aria-label={label}
          className={className ? `sd-usermenu ${className}` : "sd-usermenu"}
        >
          {/* The Avatar and the name are Button's own content row: the Avatar sits where a
              glyph does and <Text> takes Button's text padding, so the Block adds no gap. */}
          <Avatar src={avatarSrc} alt={name || "User"} size="small">
            {initials(name)}
          </Avatar>
          {name && <Text className="sd-usermenu__name">{name}</Text>}
        </Button>
      }
    >
      {items.map((item) => (
        <MenuItem key={item.id} id={item.id}>
          {item.label}
        </MenuItem>
      ))}
    </Menu>
  );
}

/* UserMenu.css — .sd-usermenu (Block)
   Arrangement only: keeps the account trigger from shrinking in shell layouts.
   Avatar, Button, and Menu own their look; trigger grouping is owned by Stack. */
.sd-usermenu {
  flex-shrink: 0;
}
